with months as (select distinct cast(date_trunc('month', date_day) as date) as month_start from {{ ref('time_spine') }}), eligible_orders as (select q.month_start, q.member_id, coalesce(o.valid_order_count, 0) as valid_order_count, coalesce(o.net_sales_cents, 0) as net_sales_cents from {{ ref('p1_qualified_member_months') }} q left join {{ ref('monthly_valid_order_activity') }} o on q.member_id = o.member_id and q.month_start = o.month_start), monthly_agg as (select month_start, sum(case when valid_order_count >= 1 then 1 else 0 end) as monthly_paid_buyer_count, sum(valid_order_count) as monthly_paid_order_count, sum(net_sales_cents) as monthly_paid_sales_cents, sum(case when valid_order_count >= 2 then 1 else 0 end) as monthly_paid_repeat_buyer_count from eligible_orders group by month_start) select m.month_start, coalesce(a.monthly_paid_buyer_count, 0) as monthly_paid_buyer_count, coalesce(a.monthly_paid_order_count, 0) as monthly_paid_order_count, coalesce(a.monthly_paid_sales_cents, 0) as monthly_paid_sales_cents, coalesce(a.monthly_paid_repeat_buyer_count, 0) as monthly_paid_repeat_buyer_count from months m left join monthly_agg a on m.month_start = a.month_start